// Keep only reviews that (a) have no owner reply, (b) have text worth answering,
// and (c) have not been drafted on a previous run.
const cfg = $('Set Review and Property Info').first().json;
const payload = $input.first().json;

if (payload && payload.error) {
  throw new Error('SerpApi returned an error: ' + payload.error);
}
if (!payload || !Array.isArray(payload.reviews)) {
  throw new Error('Response had no "reviews" array. Treating this as a broken response rather than zero results.');
}

let alreadyDrafted = new Set();
try {
  alreadyDrafted = new Set(
    $('Read Drafted Review IDs').all()
      .map(i => i.json.review_id)
      .filter(Boolean)
      .map(String)
  );
} catch (e) {
  // Sheet empty or unreadable on first run - carry on with an empty set.
}

const out = [];
for (const r of payload.reviews) {
  if (!r || typeof r !== 'object') continue;
  if (r.response) continue;

  const text = (r.snippet || '').trim();
  if (text.length < 3) continue;
  if (r.review_id && alreadyDrafted.has(String(r.review_id))) continue;

  out.push({
    json: {
      review_id: r.review_id || '',
      rating: r.rating ?? null,
      date: (r.iso_date || '').slice(0, 10),
      guest_name: (r.user && r.user.name) ? r.user.name : '',
      review_text: text,
      review_link: r.link || '',
      property_name: cfg.property_name,
      property_tone: cfg.property_tone,
      voice_examples: cfg.voice_examples || '',
      reply_language_policy: cfg.reply_language_policy,
      signature: cfg.signature,
      contact_for_offline: cfg.contact_for_offline,
      max_words: cfg.max_words
    }
  });
}

return out;

