// The LLM node returns JSON text; pair it back to the review it answers.
const review = $('Filter Unanswered Reviews').item.json;
let parsed;
try {
  parsed = JSON.parse(($json.text || $json.response || '').trim());
} catch (e) {
  throw new Error('Draft for review ' + review.review_id + ' was not valid JSON: ' + e.message);
}
const draft = (parsed.reply || '').trim();
if (!draft) {
  throw new Error('Empty draft for review ' + review.review_id + '. Not writing a blank reply to the sheet.');
}
const needsConfirmation = draft.includes('[CONFIRM') || draft.includes('[VERIFY RESERVATION');
return {
  json: {
    review_id: review.review_id,
    date: review.date,
    rating: review.rating,
    guest_name: review.guest_name,
    review_text: review.review_text,
    review_category: parsed.category || 'standard',
    draft_reply: draft,
    internal_note: parsed.internal_note || '',
    review_link: review.review_link,
    needs_confirmation: needsConfirmation,
    status: needsConfirmation ? 'NEEDS DATA' : 'PENDING APPROVAL'
  }
};

// One digest per run, not one email per review.
const cfg = $('Set Review and Property Info').first().json;
const rows = $('Match Draft to Review').all().map(i => i.json);
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const badge = (cat) => ({
  needs_reservation_verification: '🔎 Verify reservation before approving',
  possibly_fake_or_disputed: '⚠️ Possibly fake or disputed review'
})[cat] || '';
const needsData = rows.filter(r => r.needs_confirmation).length;
let html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px">';
html += '<p><b>' + rows.length + '</b> response(s) prepared for <b>' + esc(cfg.property_name) + '</b>.</p>';
html += '<p style="background:#fff4f4;border-left:4px solid #c00;padding:10px;margin:16px 0">'
     + '<b>Nothing has been published.</b> Review each draft and publish it yourself from Google.</p>';
if (needsData > 0) {
  html += '<p style="background:#fffbe6;border-left:4px solid #e6a700;padding:10px">'
       + needsData + ' draft(s) need something from you before they can be published — review the internal note for each.</p>';
}
for (const r of rows) {
  const stars = '★'.repeat(Math.max(0, Math.round(Number(r.rating) || 0)));
  const label = badge(r.review_category);
  html += '<div style="margin:26px 0;padding-top:18px;border-top:1px solid #eee">';
  html += '<p style="margin:0 0 6px"><b>' + stars + '</b> · ' + esc(r.guest_name) + ' · ' + esc(r.date);
  if (r.review_link) html += ' · <a href="' + esc(r.review_link) + '">view the review</a>';
  if (label) html += '<br><span style="color:#a15c00;font-weight:bold">' + esc(label) + '</span>';
  html += '</p>';
  html += '<blockquote style="margin:8px 0;padding:0 0 0 12px;border-left:3px solid #ddd;color:#555">' + esc(r.review_text) + '</blockquote>';
  html += '<p style="margin:12px 0 4px"><b>Public draft:</b></p>';
  html += '<div style="background:#f6f6f6;padding:12px;white-space:pre-wrap;border-radius:4px">' + esc(r.draft_reply) + '</div>';
  if (r.internal_note) {
    html += '<p style="margin:12px 0 4px"><b>Internal note (never published):</b></p>';
    html += '<div style="background:#fff8e1;padding:12px;white-space:pre-wrap;border-radius:4px;border:1px dashed #e6a700">' + esc(r.internal_note) + '</div>';
  }
  html += '</div>';
}
html += '<p style="font-size:12px;color:#888;margin-top:24px">All drafts are saved in your spreadsheet.</p></div>';
return [{
  json: {
    subject: rows.length + ' response(s) ready for approval · ' + cfg.property_name,
    html: html,
    recipient: cfg.digest_recipient,
    count: rows.length
  }
}];

